package main

import (
	"bufio"
	"fmt"
	"os"
	"path/filepath"
)

func main() {
	dir, err := os.MkdirTemp("", "read-demo")
	if err != nil {
		panic(err)
	}
	defer os.RemoveAll(dir)
	name := filepath.Join(dir, "items.txt")
	if err := os.WriteFile(name, []byte("alpha\nbeta\n"), 0o600); err != nil {
		panic(err)
	}

	all, err := os.ReadFile(name)
	if err != nil {
		panic(err)
	}
	fmt.Println("whole bytes:", len(all))

	file, err := os.Open(name)
	if err != nil {
		panic(err)
	}
	scanner := bufio.NewScanner(file)
	for scanner.Scan() {
		fmt.Println("line:", scanner.Text())
	}
	if err := scanner.Err(); err != nil {
		file.Close()
		panic(err)
	}
	if err := file.Close(); err != nil {
		panic(err)
	}
}
